CREATE TABLE IF NOT EXISTS workbench_snapshots(id TEXT PRIMARY KEY,org_id INTEGER NOT NULL,dataset TEXT NOT NULL,scope_json TEXT NOT NULL,rows_json TEXT NOT NULL,content_hash TEXT NOT NULL,created_by INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS workbench_source_artifacts(id TEXT PRIMARY KEY,org_id INTEGER NOT NULL,name TEXT NOT NULL,media_type TEXT NOT NULL,raw_base64 TEXT NOT NULL,source_hash TEXT NOT NULL,byte_length INTEGER NOT NULL,extraction_json TEXT NOT NULL,created_by INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(org_id,source_hash));
CREATE TABLE IF NOT EXISTS workbench_drafts(id TEXT PRIMARY KEY,org_id INTEGER NOT NULL,user_id INTEGER NOT NULL,dataset TEXT NOT NULL,project_id INTEGER,work_id INTEGER,revision INTEGER NOT NULL DEFAULT 1,status TEXT NOT NULL DEFAULT 'draft',source_snapshot_id TEXT,source_artifact_id TEXT,rows_json TEXT NOT NULL,steps_json TEXT NOT NULL DEFAULT '[]',lookup_refs_json TEXT NOT NULL DEFAULT '[]',recipe_version_id TEXT,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(source_snapshot_id) REFERENCES workbench_snapshots(id),FOREIGN KEY(source_artifact_id) REFERENCES workbench_source_artifacts(id));
CREATE TABLE IF NOT EXISTS workbench_recipes(id TEXT PRIMARY KEY,org_id INTEGER NOT NULL,dataset TEXT NOT NULL,name TEXT NOT NULL,created_by INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS workbench_recipe_versions(id TEXT PRIMARY KEY,org_id INTEGER NOT NULL,recipe_id TEXT NOT NULL,version_no INTEGER NOT NULL,steps_json TEXT NOT NULL,lookup_refs_json TEXT NOT NULL DEFAULT '[]',steps_hash TEXT NOT NULL,created_by INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(org_id,recipe_id,version_no),FOREIGN KEY(recipe_id) REFERENCES workbench_recipes(id));
CREATE TABLE IF NOT EXISTS workbench_validations(id TEXT PRIMARY KEY,org_id INTEGER NOT NULL,draft_id TEXT NOT NULL,draft_revision INTEGER NOT NULL,input_hash TEXT NOT NULL,result_hash TEXT NOT NULL,result_json TEXT NOT NULL,status TEXT NOT NULL,created_by INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(draft_id) REFERENCES workbench_drafts(id));
CREATE TABLE IF NOT EXISTS workbench_change_sets(id TEXT PRIMARY KEY,org_id INTEGER NOT NULL,draft_id TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1,draft_revision INTEGER NOT NULL,validation_id TEXT NOT NULL,content_hash TEXT NOT NULL,reason TEXT NOT NULL,status TEXT NOT NULL,submitted_by INTEGER NOT NULL,approved_by INTEGER,approved_at TEXT,applied_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(draft_id) REFERENCES workbench_drafts(id),FOREIGN KEY(validation_id) REFERENCES workbench_validations(id));
CREATE TABLE IF NOT EXISTS workbench_applications(id TEXT PRIMARY KEY,org_id INTEGER NOT NULL,change_set_id TEXT NOT NULL,idempotency_key TEXT NOT NULL,result_json TEXT NOT NULL,applied_by INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(org_id,idempotency_key),UNIQUE(org_id,change_set_id),FOREIGN KEY(change_set_id) REFERENCES workbench_change_sets(id));
CREATE TABLE IF NOT EXISTS workbench_lineage(id TEXT PRIMARY KEY,org_id INTEGER NOT NULL,run_type TEXT NOT NULL,source_id TEXT,engine_version TEXT NOT NULL,input_hash TEXT NOT NULL,result_hash TEXT NOT NULL,detail_json TEXT NOT NULL,created_by INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS workbench_analysis_snapshots(id TEXT PRIMARY KEY,org_id INTEGER NOT NULL,dataset TEXT NOT NULL,change_set_id TEXT,source_boundary_json TEXT NOT NULL,content_hash TEXT NOT NULL,row_count INTEGER NOT NULL,created_by INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TRIGGER IF NOT EXISTS workbench_snapshot_immutable_update BEFORE UPDATE ON workbench_snapshots BEGIN SELECT RAISE(ABORT,'workbench snapshots are immutable'); END;
CREATE TRIGGER IF NOT EXISTS workbench_snapshot_immutable_delete BEFORE DELETE ON workbench_snapshots BEGIN SELECT RAISE(ABORT,'workbench snapshots are immutable'); END;
CREATE TRIGGER IF NOT EXISTS workbench_source_artifact_immutable_update BEFORE UPDATE ON workbench_source_artifacts BEGIN SELECT RAISE(ABORT,'workbench source artifacts are immutable'); END;
CREATE TRIGGER IF NOT EXISTS workbench_source_artifact_immutable_delete BEFORE DELETE ON workbench_source_artifacts BEGIN SELECT RAISE(ABORT,'workbench source artifacts are immutable'); END;
CREATE TRIGGER IF NOT EXISTS workbench_recipe_version_immutable_update BEFORE UPDATE ON workbench_recipe_versions BEGIN SELECT RAISE(ABORT,'workbench recipe versions are immutable'); END;
CREATE TRIGGER IF NOT EXISTS workbench_recipe_version_immutable_delete BEFORE DELETE ON workbench_recipe_versions BEGIN SELECT RAISE(ABORT,'workbench recipe versions are immutable'); END;
CREATE TRIGGER IF NOT EXISTS workbench_validation_immutable_update BEFORE UPDATE ON workbench_validations BEGIN SELECT RAISE(ABORT,'workbench validations are immutable'); END;
CREATE TRIGGER IF NOT EXISTS workbench_validation_immutable_delete BEFORE DELETE ON workbench_validations BEGIN SELECT RAISE(ABORT,'workbench validations are immutable'); END;
